const { spawn } = require('child_process');
const fs = require('fs');
const path = require('path');

const projectDir = process.env.APMM_PROJECT_DIR || '/opt/foundit-apmm';
const pythonExe = process.env.APMM_PYTHON_EXE || '/opt/apmm-venv/bin/python';
const repoUrl = 'https://github.com/ankit619288/foundit-apmm-assignment';
const streamlitApp = 'https://foundit-apmm.streamlit.app/';
const finalExcel = process.env.APMM_WINNERS_PATH || path.join(projectDir, 'outputs', 'fRL_winners.xlsx');
const screenshotsDir = path.join(projectDir, 'screenshots');
const pythonEnv = { ...process.env };

if (process.env.APMM_PYTHONPATH) {
  pythonEnv.PYTHONPATH = process.env.APMM_PYTHONPATH;
}

const requiredInputs = [
  path.join('data', 'Assignment_brief.pdf'),
  path.join('data', 'Sample_Data_for_agent.xlsx'),
  path.join('data', 'purchase.xlsx'),
  path.join('data', 'winner.py')
];

const expectedOutputs = [
  path.join('outputs', 'fRL_winners.xlsx'),
  path.join('notes', 'frl_method_note.md'),
  path.join('notes', 'task1_system_prompt.md'),
  path.join('notes', 'task1_test_qna.md'),
  path.join('notes', 'task3_bonus_analysis.md'),
  'README.md',
  'requirements.txt',
  path.join('n8n', 'foundit_apmm_n8n_workflow.json')
];

function fileExists(relativePath) {
  return fs.existsSync(path.join(projectDir, relativePath));
}

function countScreenshots() {
  if (!fs.existsSync(screenshotsDir)) return 0;
  return fs.readdirSync(screenshotsDir).filter((file) => file.toLowerCase().endsWith('.png')).length;
}

function compactLog(text) {
  return String(text || '')
    .split(/\r?\n/)
    .filter((line) => /Original rows|Eligible rows|Removed rows|generated successfully|Validation PASSED|Pipeline completed|OK:|ERROR|Traceback|ModuleNotFound/i.test(line))
    .slice(-80)
    .join('\n');
}

function runCommand(args, timeoutMs = 300000) {
  return new Promise((resolve) => {
    const child = spawn(pythonExe, args, {
      cwd: projectDir,
      windowsHide: process.platform === 'win32',
      env: pythonEnv
    });

    let stdout = '';
    let stderr = '';
    let timedOut = false;

    const timer = setTimeout(() => {
      timedOut = true;
      child.kill();
    }, timeoutMs);

    child.stdout.on('data', (data) => { stdout += data.toString(); });
    child.stderr.on('data', (data) => { stderr += data.toString(); });

    child.on('close', (code) => {
      clearTimeout(timer);
      resolve({ code, timed_out: timedOut, output: `${stdout}${stderr}`.trim() });
    });

    child.on('error', (error) => {
      clearTimeout(timer);
      resolve({ code: 1, timed_out: false, output: error.message });
    });
  });
}

const inputChecks = requiredInputs.map((file) => ({ file, exists: fileExists(file) }));
const missingInputs = inputChecks.filter((item) => !item.exists).map((item) => item.file);

if (missingInputs.length > 0) {
  return [{ json: {
    workflow: 'foundit APMM n8n pipeline',
    status: 'Failed',
    stage: 'Input validation',
    message: 'Required assignment input files are missing.',
    missing_inputs: missingInputs,
    input_checks: inputChecks,
    pipeline_ran: false,
    final_excel_exists: fs.existsSync(finalExcel),
    github_repo: repoUrl,
    streamlit_app: streamlitApp,
    final_excel: 'outputs/fRL_winners.xlsx'
  }}];
}

const pythonCheck = await runCommand(['-c', 'import sys; import pandas, openpyxl, pypdf, plotly, streamlit; print(sys.executable); print("python dependencies ok")'], 60000);

if (pythonCheck.code !== 0) {
  return [{ json: {
    workflow: 'foundit APMM n8n pipeline',
    status: 'Failed',
    stage: 'Python dependency check',
    message: 'Python dependencies are not available to the n8n runner.',
    selected_python: pythonExe,
    python_check_output: pythonCheck.output,
    pipeline_ran: false,
    final_excel_exists: fs.existsSync(finalExcel),
    input_checks: inputChecks,
    github_repo: repoUrl,
    streamlit_app: streamlitApp,
    final_excel: 'outputs/fRL_winners.xlsx'
  }}];
}

const pipeline = await runCommand(['run_pipeline.py'], 300000);
const outputChecks = expectedOutputs.map((file) => ({ file, exists: fileExists(file) }));
const missingOutputs = outputChecks.filter((item) => !item.exists).map((item) => item.file);
const screenshotsCount = countScreenshots();
const pipelineCompleted = pipeline.code === 0 && pipeline.output.toLowerCase().includes('pipeline completed');
const finalExcelExists = fs.existsSync(finalExcel);
const submissionReady = pipelineCompleted && finalExcelExists && missingOutputs.length === 0 && screenshotsCount >= 3;

return [{ json: {
  workflow: 'foundit APMM n8n pipeline',
  status: submissionReady ? 'Success' : 'Failed',
  stage: submissionReady ? 'Submission ready' : 'Output validation',
  message: submissionReady
    ? 'APMM pipeline completed successfully. Final Excel, notes, README, screenshots, and n8n workflow export are available.'
    : 'Pipeline ran but one or more submission checks need review.',
  selected_python: pythonExe,
  pipeline_ran: pipelineCompleted,
  final_excel_exists: finalExcelExists,
  screenshots_count: screenshotsCount,
  missing_outputs: missingOutputs,
  input_checks: inputChecks,
  output_checks: outputChecks,
  github_repo: repoUrl,
  streamlit_app: streamlitApp,
  final_excel: 'outputs/fRL_winners.xlsx',
  python_check_output: pythonCheck.output,
  pipeline_output: compactLog(pipeline.output)
}}];

const fs = require('fs');
const path = require('path');

const projectDir = process.env.APMM_PROJECT_DIR || '/opt/foundit-apmm';
const filePath = process.env.APMM_PURCHASE_PATH || path.join(projectDir, 'data', 'purchase.xlsx');

if (fs.existsSync(filePath)) {
  fs.unlinkSync(filePath);
}

return $input.all();
